// Dependency-free sourcemap byte attribution.
// Walks mappings in generated order; attributes the generated bytes between
// consecutive mapping positions to the source file of the earlier mapping.
import fs from 'fs';
import path from 'path';

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const CH = new Map([...B64].map((c, i) => [c, i]));

function decodeVLQ(str) {
  const out = [];
  let shift = 0, value = 0;
  for (const c of str) {
    let d = CH.get(c);
    if (d === undefined) throw new Error('bad char ' + c);
    const cont = d & 32;
    d &= 31;
    value += d << shift;
    if (cont) { shift += 5; }
    else {
      const neg = value & 1;
      value >>= 1;
      out.push(neg ? (value === 0 ? -0x80000000 : -value) : value);
      value = 0; shift = 0;
    }
  }
  return out;
}

const jsFile = process.argv[2];
const mapFile = jsFile + '.map';
const code = fs.readFileSync(jsFile, 'utf8');
const map = JSON.parse(fs.readFileSync(mapFile, 'utf8'));

// line start offsets in generated code
const lineStarts = [0];
for (let i = 0; i < code.length; i++) if (code[i] === '\n') lineStarts.push(i + 1);
const totalBytes = Buffer.byteLength(code);

// decode all mappings into [genLine, genCol, srcIdx]
const segs = [];
let srcIdx = 0, srcLine = 0, srcCol = 0, nameIdx = 0;
const lines = map.mappings.split(';');
for (let gl = 0; gl < lines.length; gl++) {
  let genCol = 0;
  const seg = lines[gl];
  if (!seg) continue;
  for (const s of seg.split(',')) {
    if (!s) continue;
    const f = decodeVLQ(s);
    genCol += f[0];
    if (f.length >= 4) {
      srcIdx += f[1]; srcLine += f[2]; srcCol += f[3];
      if (f.length >= 5) nameIdx += f[4];
      segs.push([gl, genCol, srcIdx]);
    } else {
      segs.push([gl, genCol, -1]); // unmapped
    }
  }
}

function absOffset(line, col) {
  if (line >= lineStarts.length) return code.length;
  return Math.min(lineStarts[line] + col, code.length);
}

const bySource = new Map();
let unmapped = 0;
for (let i = 0; i < segs.length; i++) {
  const [gl, gc, si] = segs[i];
  const start = absOffset(gl, gc);
  const next = segs[i + 1];
  const end = next ? absOffset(next[0], next[1]) : code.length;
  const len = Math.max(0, end - start);
  if (si < 0) { unmapped += len; continue; }
  const name = map.sources[si] ?? ('#' + si);
  bySource.set(name, (bySource.get(name) || 0) + len);
}

// Group by npm package / app area
function group(src) {
  const m = src.match(/node_modules\/\.pnpm\/([^/]+)\/node_modules\/(@[^/]+\/[^/]+|[^/]+)/);
  if (m) return 'npm:' + m[2];
  const m2 = src.match(/node_modules\/(@[^/]+\/[^/]+|[^/]+)/);
  if (m2) return 'npm:' + m2[1];
  if (src.includes('/shared/')) return 'app:@ship/shared';
  if (src.includes('/src/')) {
    const m3 = src.match(/\/src\/([^/]+)/);
    return 'app:src/' + (m3 ? m3[1] : '');
  }
  return 'other:' + src;
}

const groups = new Map();
for (const [s, n] of bySource) {
  const g = group(s);
  groups.set(g, (groups.get(g) || 0) + n);
}

const K = (n) => (n / 1000).toFixed(1);
const accounted = [...bySource.values()].reduce((a, b) => a + b, 0);
console.log(`FILE ${path.basename(jsFile)}  totalBytes=${K(totalBytes)} kB  attributed=${K(accounted)} kB  unmapped=${K(unmapped)} kB`);
console.log('\n--- BY PACKAGE / AREA (raw minified bytes) ---');
[...groups.entries()].sort((a, b) => b[1] - a[1]).slice(0, 45)
  .forEach(([g, n]) => console.log(String(K(n)).padStart(9) + ' kB  ' + (100 * n / totalBytes).toFixed(1).padStart(5) + '%  ' + g));

console.log('\n--- TOP 30 INDIVIDUAL SOURCE FILES ---');
[...bySource.entries()].sort((a, b) => b[1] - a[1]).slice(0, 30)
  .forEach(([s, n]) => console.log(String(K(n)).padStart(9) + ' kB  ' + s.replace(/^.*node_modules\/(\.pnpm\/[^/]+\/node_modules\/)?/, 'nm:')));
